  ('64d7e442-7d6e-4882-9479-47bf526a88e7'::uuid, '{"en":"Mech Suit Up","zh":"机甲变身","zh-Hant":"機甲變身","ja":"メカ変身"}'::jsonb, '{"en":"Create a mech suit transformation video for me, referencing the mech design blueprints in the skill.","zh":"帮我做一条机甲变身视频，参考skill里的机甲设计图","zh-Hant":"幫我做一條機甲變身影片，參考skill裡的機甲設計圖","ja":"スキル内のメカデザイン設計図を参考にして、メカ変身ビデオを作成してください。"}'::jsonb),
  ('5aeca716-9d76-47d9-9c01-0a81308639f9'::uuid, '{"en":"✍️ Daily Annotation","zh":"✍️ 美食手帐标注","zh-Hant":"✍️ 美食手帳標註","ja":"✍️ フード手帳注釈"}'::jsonb, '{"en":"Add hand-drawn annotation style to my food photo","zh":"为我的美食照片添加手绘标注风格","zh-Hant":"為我的美食照片添加手繪標註風格","ja":"私の食べ物の写真に手書きの注釈スタイルを追加してください。"}'::jsonb),
  ('a25030c8-5ecb-45fc-846e-ee929475b806'::uuid, '{"en":"Triple Shot","zh":"三连拍合影","zh-Hant":"三連拍合影","ja":"トリプルショット"}'::jsonb, '{"en":"Upload idol + fan photos, generate a 3-frame vertical photo strip with expression progression","zh":"上传偶像+粉丝照片，生成一张带有表情变化的3格竖版照片条","zh-Hant":"上傳偶像+粉絲照片，生成一張帶有表情變化的3格豎版照片條","ja":"アイドルとファンの写真をアップロードして、表情の変化がある3コマの縦長フォトストリップを生成してください。"}'::jsonb),
  ('c44b1d23-a164-40e7-811c-90255f5b3dc6'::uuid, '{"en":"Flash Snap","zh":"闪光灯抓拍","zh-Hant":"閃光燈抓拍","ja":"フラッシュスナップ"}'::jsonb, '{"en":"Upload idol + fan photos, generate a flash photography candid shot in dark environment","zh":"上传偶像+粉丝照片，生成一张在黑暗环境中的闪光灯抓拍照片","zh-Hant":"上傳偶像+粉絲照片，生成一張在黑暗環境中的閃光燈抓拍照片","ja":"アイドルとファンの写真をアップロードして、暗い環境でフラッシュ撮影による自然なスナップショットを生成してください。"}'::jsonb),
