  ('2d8de8a4-9341-45da-9c79-657e4e743180'::uuid, '{"en":"Photo Booth","zh":"大头贴","zh-Hant":"大頭貼","ja":"プリクラ"}'::jsonb, '{"en":"Upload idol + fan photos, generate a Japanese purikura 4-frame photo booth strip","zh":"上传偶像+粉丝照片，生成一张日式大头贴风格的4格照片条","zh-Hant":"上傳偶像+粉絲照片，生成一張日式大頭貼風格的4格照片條","ja":"アイドルとファンの写真をアップロードして、日本のプリクラ風4コマフォトブースストリップを生成してください。"}'::jsonb),
  ('5c15e64d-0eef-4ed4-b106-841eea3264f5'::uuid, '{"en":"Fisheye Selfie","zh":"鱼眼自拍","zh-Hant":"魚眼自拍","ja":"魚眼自撮り"}'::jsonb, '{"en":"Upload idol + fan photos, generate an overhead fisheye big-head goofy selfie","zh":"上传偶像+粉丝照片，生成一张俯视鱼眼大头搞怪自拍","zh-Hant":"上傳偶像+粉絲照片，生成一張俯視魚眼大頭搞怪自拍","ja":"アイドルとファンの写真をアップロードして、頭上からの魚眼レンズで撮ったような、頭が大きく写ったおかしな自撮り写真を生成して"}'::jsonb),
  ('a1cadab3-3577-42fb-b199-1703b4cbc9d7'::uuid, '{"en":"Variety Show","zh":"综艺名场面","zh-Hant":"綜藝名場面","ja":"バラエティ番組名場面"}'::jsonb, '{"en":"Upload idol + fan photos, generate a variety show TV screenshot with flower text effects","zh":"上传偶像+粉丝照片，生成一张带有花字效果的综艺节目电视截图","zh-Hant":"上傳偶像+粉絲照片，生成一張帶有花字效果的綜藝節目電視截圖","ja":"アイドルとファンの写真をアップロードして、花文字エフェクト付きのバラエティ番組のテレビ画面を生成して"}'::jsonb),
