  ('fe06677e-b112-451c-a0c1-b7a83b1cb8c2'::uuid, '{"en":"Photo Peel","zh":"撕纸人像","zh-Hant":"撕紙人像","ja":"写真剥がし"}'::jsonb, '{"en":"Drop a photo — peel your person out like a 2D sticker.","zh":"上传一张照片，把照片里的人物像2D贴纸一样剥离出来。","zh-Hant":"上傳一張照片，將照片裡的人物像2D貼紙一樣剝離出來。","ja":"写真をドロップして、人物を2Dステッカーのように剥がし出してください。"}'::jsonb),
  ('4c711043-a8bc-4e46-9d2e-acc573a7e585'::uuid, '{"en":"Flash Cut Travel","zh":"10秒闪切旅拍","zh-Hant":"10秒閃切旅拍","ja":"フラッシュカット旅行"}'::jsonb, '{"en":"Upload travel photos and generate a 10-second fast-cut travel video.","zh":"上传旅行照片，生成一个10秒的快速剪辑旅行视频。","zh-Hant":"上傳旅行照片，生成一個10秒的快速剪輯旅行影片。","ja":"旅行写真をアップロードして、10秒の高速編集旅行動画を生成してください。"}'::jsonb),
  ('3efd5636-0650-4ef7-9b48-5e6dda55989a'::uuid, '{"en":"Card Summon","zh":"卡牌召唤","zh-Hant":"卡牌召喚","ja":"カード召喚"}'::jsonb, '{"en":"Summon your idol from a glowing card — the card shatters and they appear in a burst of light","zh":"从一张发光的卡牌中召唤我的偶像——卡牌破碎，偶像在光芒中出现。","zh-Hant":"從一張發光的卡牌中召喚我的偶像——卡牌破碎，偶像在光芒中出現。","ja":"光り輝くカードからアイドルを召喚してください — カードが砕け散り、光の爆発とともにアイドルが現れます。"}'::jsonb),
  ('1094df13-6ba9-476b-b6b5-b22e483baa96'::uuid, '{"en":"Concert Poster Tour","zh":"海报巡演","zh-Hant":"海報巡演","ja":"コンサートポスターツアー"}'::jsonb, '{"en":"Turn yourself into a concert poster that comes alive — lights flash, crowd roars, your tour begins","zh":"把我变成一张活生生的演唱会海报——灯光闪烁，人群欢呼，我的巡演开始。","zh-Hant":"把我變成一張活生生的演唱會海報——燈光閃爍，人群歡呼，我的巡演開始。","ja":"私を生き生きとしたコンサートポスターに変えてください — ライトが点滅し、群衆が歓声を上げ、私のツアーが始まります。"}'::jsonb),
  ('159e113d-c1c4-45d9-8c6a-93ba45e73203'::uuid, '{"en":"Cyber Samurai Duel","zh":"赛博对决","zh-Hant":"賽博對決","ja":"サイバー侍の決闘"}'::jsonb, '{"en":"Upload two photos and watch them clash in a cinematic cyber samurai duel.","zh":"上传两张照片，观看它们在电影般的赛博武士对决中激烈碰撞。","zh-Hant":"上傳兩張照片，觀看它們在電影般的賽博武士對決中激烈碰撞。","ja":"2枚の写真をアップロードして、映画のようなサイバー侍の決闘で激突する様子を見せてください。"}'::jsonb),
  ('dada27b1-9234-4d30-9a00-0785954833f8'::uuid, '{"en":"Multiverse Fall","zh":"坠入多重宇宙","zh-Hant":"墜入多重宇宙","ja":"マルチバースへの墜落"}'::jsonb, '{"en":"Drop yourself through parallel dimensions — each portal reveals a different universe version of you","zh":"让我坠入平行维度——每个传送门都会展现一个不同宇宙版本的我","zh-Hant":"讓我墜入平行維度——每個傳送門都會展現一個不同宇宙版本的我","ja":"平行次元を通り抜けさせてください。それぞれのポータルからは、異なる宇宙の私が現れます。"}'::jsonb),
  ('dae88473-de10-40ca-815d-0473a8898eef'::uuid, '{"en":"Fan Meeting","zh":"爱豆签售会","zh-Hant":"偶像簽售會","ja":"アイドルサイン会"}'::jsonb, '{"en":"Upload a selfie to become a K-pop idol at your own fan signing event.","zh":"上传一张自拍，让你在自己的粉丝签售会上成为一名K-pop偶像。","zh-Hant":"上傳一張自拍，讓你在自己的粉絲簽售會上成為一名K-pop偶像。","ja":"自撮り写真をアップロードして、自分のファンサイン会でK-POPアイドルになろう。"}'::jsonb),
  ('7daee2f9-afff-49d1-8d0c-c802f9bdf171'::uuid, '{"en":"Pitch to Universe","zh":"投球宇宙","zh-Hant":"投球宇宙","ja":"宇宙への投球"}'::jsonb, '{"en":"Pitch a ball that tears through reality — watch it fly into the cosmos and shatter dimensions","zh":"投一个撕裂现实的球——看着它飞向宇宙并粉碎维度","zh-Hant":"投一個撕裂現實的球——看著它飛向宇宙並粉碎維度","ja":"現実を突き破るボールを投げて、それが宇宙へ飛び立ち、次元を粉砕するのを見てください。"}'::jsonb),
