  ('e387dc1d-22c1-493a-8521-dc3c66be96de'::uuid, '{"en":"Living Billboard","zh":"双面人生","zh-Hant":"活生生的廣告牌","ja":"生きる広告"}'::jsonb, '{"en":"Step out of a billboard as your real self — the poster version watches as you come to life","zh":"我从广告牌中走出，以真实的自我出现，海报中的我则在一旁看着我活过来。","zh-Hant":"我從廣告牌中走出，以真實的自我出現，海報中的我則在一旁看著我活過來。","ja":"広告看板から本当の自分として現れる私。ポスターの私が、私が命を吹き込まれるのを見守っている。"}'::jsonb),
  ('b1699762-5207-480a-91e2-dd5eb6909bb3'::uuid, '{"en":"Puppet Master","zh":"提线木偶","zh-Hant":"提線木偶","ja":"操り人形"}'::jsonb, '{"en":"Turn yourself into a BJD marionette — strings descend, joints lock, and the puppet master pulls you to life","zh":"将自己变成一个BJD提线木偶——细线垂下，关节锁住，提线木偶师将你拉向生命","zh-Hant":"將自己變成一個BJD提線木偶——細線垂下，關節鎖住，提線木偶師將你拉向生命","ja":"自分をBJDの操り人形に変えてください――糸が垂れ下がり、関節が固定され、操り人形師があなたに命を吹き込みます"}'::jsonb),
