  ('29fbd6f2-c3f1-40b6-92df-f3094e0bbb33'::uuid, '{"en":"Mecha Unmask","zh":"机甲归真","zh-Hant":"機甲歸真","ja":"メカの素顔"}'::jsonb, '{"en":"Transform your photo into a mecha pilot reveal — armor peels away to unveil the real you","zh":"将你的照片转化为机甲驾驶员揭示真面目的场景——装甲剥落，展现真实的你","zh-Hant":"將你的照片轉化為機甲駕駛員揭示真面目的場景——裝甲剝落，展現真實的你","ja":"あなたの写真を、装甲が剥がれ落ちて本当のあなたが現れるメカパイロットの素顔公開シーンに変換して"}'::jsonb),
  ('912fe012-0371-4401-bea2-d9bf93052d00'::uuid, '{"en":"Magic Awakening","zh":"魔法觉醒","zh-Hant":"魔法覺醒","ja":"魔法覚醒"}'::jsonb, '{"en":"Awaken your hidden magic — energy surges from within and transforms you into a cinematic sorcerer","zh":"唤醒你隐藏的魔法——能量从体内涌出，将你变成一个电影般的巫师","zh-Hant":"喚醒你隱藏的魔法——能量從體內湧出，將你變成一個電影般的巫師","ja":"隠された魔法を覚醒させてください。内からエネルギーが湧き上がり、私を映画のような魔術師に変えてください。"}'::jsonb),
  ('4e63ccd3-30e0-4ee9-99ed-dc787bb17e2f'::uuid, '{"en":"Music Card","zh":"音乐卡片","zh-Hant":"音樂卡片","ja":"ミュージックカード"}'::jsonb, '{"en":"Transform your photo into a music video: walk, put on headphones, and floating frosted-glass music player cards fly in and orbit around you.","zh":"将我的照片制作成音乐视频：我正在走路，戴着耳机，磨砂玻璃音乐播放器卡片漂浮着飞入并围绕我旋转。","zh-Hant":"將我的照片製作成音樂影片：我正在走路，戴著耳機，磨砂玻璃音樂播放器卡片漂浮著飛入並圍繞我旋轉。","ja":"私の写真をミュージックビデオに変換してください。私が歩き、ヘッドホンをつけ、曇りガラスの音楽プレイヤーカードが浮遊しながら飛び込み、私の周りを周回する様子を描写してください。"}'::jsonb),
  ('c96c9633-117d-4f62-ac0a-286fff2b531f'::uuid, '{"en":"Outfit Roulette","zh":"出道变身","zh-Hant":"造型輪盤","ja":"衣装ルーレット"}'::jsonb, '{"en":"Spin the roulette and debut in a random stage outfit — a new look every time you hit play","zh":"转动轮盘，随机生成一套舞台服装出道——每次点击播放都会有新造型。","zh-Hant":"轉動輪盤，隨機生成一套舞台服裝出道——每次點擊播放都會有新造型。","ja":"ルーレットを回して、ランダムなステージ衣装でデビューしたい。再生するたびに新しいルックになるよ。"}'::jsonb),
  ('88adcd41-0546-42bb-87ab-5b409f855ab8'::uuid, '{"en":"Rain Control","zh":"控雨术","zh-Hant":"控雨術","ja":"雨を操る"}'::jsonb, '{"en":"Upload your photo and control the rain with a wave of your hand.","zh":"上传你的照片，挥手控制雨水。","zh-Hant":"上傳你的照片，揮手控制雨水。","ja":"写真をアップロードして、手を振って雨をコントロールしてください。"}'::jsonb)
)
UPDATE public.home_skills AS skill
SET labels = localized.labels || COALESCE(skill.labels, '{}'::jsonb),
    prompts = localized.prompts || COALESCE(skill.prompts, '{}'::jsonb),
    updated_at = now()
FROM localized_skill_copy AS localized
WHERE skill.id = localized.id;
